window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-840cebc26558507d"]={"versions": [{"id": "FIG-840cebc26558507d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Speicherzugriffsdiagramm des AUTOSAR ADC Drivers (MCAL). Das Diagramm veranschaulicht den Datenfluss und das Puffer-Handling beim Ergebniszugriff über die API-Funktion <code>Adc_ReadGroup</code> zwischen Hardware-Registern, dem ADC-Treiberpuffer und dem anwendungsspezifischen Lesepuffer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier architektonische Domänen bzw. Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>ADC HW</strong>: Beinhaltet die Hardware-Ergebnisregister (<code>HW result register</code>), auf die kein direkter Zugriff über ADC-API-Funktionen unterstützt wird (Hinweistext: <em>„no direct access via ADC API functions supported to ADC HW result register“</em>).</li>\n<li><strong>ADC Driver</strong>: Verantwortlich für das Auslesen der HW-Register und die Zwischenspeicherung in anwendungsseitigen Puffern.</li>\n<li><strong>Application – result buffer (required)</strong>:</li>\n<li><code>G1_ResultBuffer[6]</code>: Puffer für Kanalgruppe 1 mit 6 Elementen, angeordnet als wiederkehrende Sequenzen von <code>G1-CH0</code> und <code>G1-CH1</code> (für 3 Konvertierungsrunden).</li>\n<li><code>G2_ResultBuffer[2]</code>: Puffer für Kanalgruppe 2 mit 2 Elementen (<code>G2-CH2</code> über 2 Konvertierungsrunden).</li>\n<li><code>G3_ResultBuffer[1]</code>: Puffer für Kanalgruppe 3 mit 1 Element (<code>G3-CH3</code> über 1 Konvertierungsrunde).</li>\n<li>Schraffierte Pufferfelder kennzeichnen die Daten der jeweils letzten Konvertierungsrunde (<em>„result of last conversion round“</em>).</li>\n<li><strong>Application – read buffer (required if Adc_ReadGroup is used)</strong>:</li>\n<li><code>G1_ReadBuffer[2]</code>: Lesepuffer für Gruppe 1 mit Feldern für <code>G1-CH0</code> und <code>G1-CH1</code>.</li>\n<li><code>G2_G3_ReadBuffer[1]</code>: Geteilter/wiederverwendeter Lesepuffer für die Einzelkanal-Gruppen 2 oder 3 (<code>G2_CH2 or G3-CH3</code>).</li>\n<li><strong>Schnittstelle</strong>:</li>\n<li>API-Funktion <code>Adc_ReadGroup</code>, welche als Kopiermechanismus zwischen Result Buffer und Read Buffer agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der ADC Driver transferiert Konvertierungsergebnisse aus den <code>HW result register</code> in den jeweiligen anwendungsseitigen <code>result buffer</code> (<code>G1_ResultBuffer</code>, <code>G2_ResultBuffer</code>, <code>G3_ResultBuffer</code>).</li>\n<li>Mehrfach-Konvertierungsrunden werden im <code>result buffer</code> historisiert bzw. akkumuliert (z. B. 3 Runden für G1, 2 Runden für G2, 1 Runde für G3).</li>\n<li>Bei Aufruf von <code>Adc_ReadGroup</code> kopiert der ADC Driver gezielt ausschließlich die Daten der jeweils jüngsten Konvertierungsrunde (<em>„result of last conversion round“</em>, schraffiert dargestellt) aus dem <code>result buffer</code> in den anwendungseigenen <code>read buffer</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für Gruppe 1 werden das schraffierte <code>G1-CH0</code> und <code>G1-CH1</code> in <code>G1_ReadBuffer[2]</code> übertragen.</li>\n<li>Für Gruppe 2 bzw. Gruppe 3 wird das jeweils aktuelle Element (<code>G2-CH2</code> oder <code>G3-CH3</code>) in den gemeinsamen Lesepuffer <code>G2_G3_ReadBuffer[1]</code> kopiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bereitstellung eines Ergebnis-Puffers (<code>result buffer</code>) ist für den Betrieb des ADC Drivers zwingend vorgeschrieben (<code>required</code>).</li>\n<li>Der Lesepuffer (<code>read buffer</code>) ist nur dann erforderlich, wenn Konvertierungsergebnisse über die API <code>Adc_ReadGroup</code> abgerufen werden (<code>required if Adc_ReadGroup is used</code>).</li>\n<li>Direkte Zugriffe der Applikation auf die Hardware-Ergebnisregister über die ADC-Schnittstelle sind normativ untersagt bzw. nicht vorgesehen.</li>\n<li><code>Adc_ReadGroup</code> entkoppelt die Weiterverarbeitung von vorherigen Konvertierungsrunden im Streaming-/Ringpuffer, indem immer nur der Snapshot der jeweils letzten Konvertierungsrunde (ein Messwert pro konfiguriertem Gruppenkanal) in den Zielpuffer übertragen wird.</li>\n<li>Lesepuffer können für disjunkte Gruppenabrufe im Speicher wiederverwendet werden, sofern die Puffergröße mindestens der Kanalanzahl der größten abgefragten Gruppe entspricht.</li>\n</ul>"}, {"id": "FIG-4fd4e2d280948a07", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Speicherzugriffsdiagramm des AUTOSAR ADC Drivers (MCAL). Das Diagramm veranschaulicht den Datenfluss und das Puffer-Handling beim Ergebniszugriff über die API-Funktion <code>Adc_ReadGroup</code> zwischen Hardware-Registern, dem ADC-Treiberpuffer und dem anwendungsspezifischen Lesepuffer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier architektonische Domänen bzw. Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>ADC HW</strong>: Beinhaltet die Hardware-Ergebnisregister (<code>HW result register</code>), auf die kein direkter Zugriff über ADC-API-Funktionen unterstützt wird (Hinweistext: <em>„no direct access via ADC API functions supported to ADC HW result register“</em>).</li>\n<li><strong>ADC Driver</strong>: Verantwortlich für das Auslesen der HW-Register und die Zwischenspeicherung in anwendungsseitigen Puffern.</li>\n<li><strong>Application – result buffer (required)</strong>:</li>\n<li><code>G1_ResultBuffer[6]</code>: Puffer für Kanalgruppe 1 mit 6 Elementen, angeordnet als wiederkehrende Sequenzen von <code>G1-CH0</code> und <code>G1-CH1</code> (für 3 Konvertierungsrunden).</li>\n<li><code>G2_ResultBuffer[2]</code>: Puffer für Kanalgruppe 2 mit 2 Elementen (<code>G2-CH2</code> über 2 Konvertierungsrunden).</li>\n<li><code>G3_ResultBuffer[1]</code>: Puffer für Kanalgruppe 3 mit 1 Element (<code>G3-CH3</code> über 1 Konvertierungsrunde).</li>\n<li>Schraffierte Pufferfelder kennzeichnen die Daten der jeweils letzten Konvertierungsrunde (<em>„result of last conversion round“</em>).</li>\n<li><strong>Application – read buffer (required if Adc_ReadGroup is used)</strong>:</li>\n<li><code>G1_ReadBuffer[2]</code>: Lesepuffer für Gruppe 1 mit Feldern für <code>G1-CH0</code> und <code>G1-CH1</code>.</li>\n<li><code>G2_G3_ReadBuffer[1]</code>: Geteilter/wiederverwendeter Lesepuffer für die Einzelkanal-Gruppen 2 oder 3 (<code>G2_CH2 or G3-CH3</code>).</li>\n<li><strong>Schnittstelle</strong>:</li>\n<li>API-Funktion <code>Adc_ReadGroup</code>, welche als Kopiermechanismus zwischen Result Buffer und Read Buffer agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der ADC Driver transferiert Konvertierungsergebnisse aus den <code>HW result register</code> in den jeweiligen anwendungsseitigen <code>result buffer</code> (<code>G1_ResultBuffer</code>, <code>G2_ResultBuffer</code>, <code>G3_ResultBuffer</code>).</li>\n<li>Mehrfach-Konvertierungsrunden werden im <code>result buffer</code> historisiert bzw. akkumuliert (z. B. 3 Runden für G1, 2 Runden für G2, 1 Runde für G3).</li>\n<li>Bei Aufruf von <code>Adc_ReadGroup</code> kopiert der ADC Driver gezielt ausschließlich die Daten der jeweils jüngsten Konvertierungsrunde (<em>„result of last conversion round“</em>, schraffiert dargestellt) aus dem <code>result buffer</code> in den anwendungseigenen <code>read buffer</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für Gruppe 1 werden das schraffierte <code>G1-CH0</code> und <code>G1-CH1</code> in <code>G1_ReadBuffer[2]</code> übertragen.</li>\n<li>Für Gruppe 2 bzw. Gruppe 3 wird das jeweils aktuelle Element (<code>G2-CH2</code> oder <code>G3-CH3</code>) in den gemeinsamen Lesepuffer <code>G2_G3_ReadBuffer[1]</code> kopiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bereitstellung eines Ergebnis-Puffers (<code>result buffer</code>) ist für den Betrieb des ADC Drivers zwingend vorgeschrieben (<code>required</code>).</li>\n<li>Der Lesepuffer (<code>read buffer</code>) ist nur dann erforderlich, wenn Konvertierungsergebnisse über die API <code>Adc_ReadGroup</code> abgerufen werden (<code>required if Adc_ReadGroup is used</code>).</li>\n<li>Direkte Zugriffe der Applikation auf die Hardware-Ergebnisregister über die ADC-Schnittstelle sind normativ untersagt bzw. nicht vorgesehen.</li>\n<li><code>Adc_ReadGroup</code> entkoppelt die Weiterverarbeitung von vorherigen Konvertierungsrunden im Streaming-/Ringpuffer, indem immer nur der Snapshot der jeweils letzten Konvertierungsrunde (ein Messwert pro konfiguriertem Gruppenkanal) in den Zielpuffer übertragen wird.</li>\n<li>Lesepuffer können für disjunkte Gruppenabrufe im Speicher wiederverwendet werden, sofern die Puffergröße mindestens der Kanalanzahl der größten abgefragten Gruppe entspricht.</li>\n</ul>"}, {"id": "FIG-be91df9ce822a9ba", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Speicherzugriffsdiagramm des AUTOSAR ADC Drivers (MCAL). Das Diagramm veranschaulicht den Datenfluss und das Puffer-Handling beim Ergebniszugriff über die API-Funktion <code>Adc_ReadGroup</code> zwischen Hardware-Registern, dem ADC-Treiberpuffer und dem anwendungsspezifischen Lesepuffer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier architektonische Domänen bzw. Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>ADC HW</strong>: Beinhaltet die Hardware-Ergebnisregister (<code>HW result register</code>), auf die kein direkter Zugriff über ADC-API-Funktionen unterstützt wird (Hinweistext: <em>„no direct access via ADC API functions supported to ADC HW result register“</em>).</li>\n<li><strong>ADC Driver</strong>: Verantwortlich für das Auslesen der HW-Register und die Zwischenspeicherung in anwendungsseitigen Puffern.</li>\n<li><strong>Application – result buffer (required)</strong>:</li>\n<li><code>G1_ResultBuffer[6]</code>: Puffer für Kanalgruppe 1 mit 6 Elementen, angeordnet als wiederkehrende Sequenzen von <code>G1-CH0</code> und <code>G1-CH1</code> (für 3 Konvertierungsrunden).</li>\n<li><code>G2_ResultBuffer[2]</code>: Puffer für Kanalgruppe 2 mit 2 Elementen (<code>G2-CH2</code> über 2 Konvertierungsrunden).</li>\n<li><code>G3_ResultBuffer[1]</code>: Puffer für Kanalgruppe 3 mit 1 Element (<code>G3-CH3</code> über 1 Konvertierungsrunde).</li>\n<li>Schraffierte Pufferfelder kennzeichnen die Daten der jeweils letzten Konvertierungsrunde (<em>„result of last conversion round“</em>).</li>\n<li><strong>Application – read buffer (required if Adc_ReadGroup is used)</strong>:</li>\n<li><code>G1_ReadBuffer[2]</code>: Lesepuffer für Gruppe 1 mit Feldern für <code>G1-CH0</code> und <code>G1-CH1</code>.</li>\n<li><code>G2_G3_ReadBuffer[1]</code>: Geteilter/wiederverwendeter Lesepuffer für die Einzelkanal-Gruppen 2 oder 3 (<code>G2_CH2 or G3-CH3</code>).</li>\n<li><strong>Schnittstelle</strong>:</li>\n<li>API-Funktion <code>Adc_ReadGroup</code>, welche als Kopiermechanismus zwischen Result Buffer und Read Buffer agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der ADC Driver transferiert Konvertierungsergebnisse aus den <code>HW result register</code> in den jeweiligen anwendungsseitigen <code>result buffer</code> (<code>G1_ResultBuffer</code>, <code>G2_ResultBuffer</code>, <code>G3_ResultBuffer</code>).</li>\n<li>Mehrfach-Konvertierungsrunden werden im <code>result buffer</code> historisiert bzw. akkumuliert (z. B. 3 Runden für G1, 2 Runden für G2, 1 Runde für G3).</li>\n<li>Bei Aufruf von <code>Adc_ReadGroup</code> kopiert der ADC Driver gezielt ausschließlich die Daten der jeweils jüngsten Konvertierungsrunde (<em>„result of last conversion round“</em>, schraffiert dargestellt) aus dem <code>result buffer</code> in den anwendungseigenen <code>read buffer</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für Gruppe 1 werden das schraffierte <code>G1-CH0</code> und <code>G1-CH1</code> in <code>G1_ReadBuffer[2]</code> übertragen.</li>\n<li>Für Gruppe 2 bzw. Gruppe 3 wird das jeweils aktuelle Element (<code>G2-CH2</code> oder <code>G3-CH3</code>) in den gemeinsamen Lesepuffer <code>G2_G3_ReadBuffer[1]</code> kopiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bereitstellung eines Ergebnis-Puffers (<code>result buffer</code>) ist für den Betrieb des ADC Drivers zwingend vorgeschrieben (<code>required</code>).</li>\n<li>Der Lesepuffer (<code>read buffer</code>) ist nur dann erforderlich, wenn Konvertierungsergebnisse über die API <code>Adc_ReadGroup</code> abgerufen werden (<code>required if Adc_ReadGroup is used</code>).</li>\n<li>Direkte Zugriffe der Applikation auf die Hardware-Ergebnisregister über die ADC-Schnittstelle sind normativ untersagt bzw. nicht vorgesehen.</li>\n<li><code>Adc_ReadGroup</code> entkoppelt die Weiterverarbeitung von vorherigen Konvertierungsrunden im Streaming-/Ringpuffer, indem immer nur der Snapshot der jeweils letzten Konvertierungsrunde (ein Messwert pro konfiguriertem Gruppenkanal) in den Zielpuffer übertragen wird.</li>\n<li>Lesepuffer können für disjunkte Gruppenabrufe im Speicher wiederverwendet werden, sofern die Puffergröße mindestens der Kanalanzahl der größten abgefragten Gruppe entspricht.</li>\n</ul>"}, {"id": "FIG-90732dabb33b938b", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Speicherzugriffsdiagramm des AUTOSAR ADC Drivers (MCAL). Das Diagramm veranschaulicht den Datenfluss und das Puffer-Handling beim Ergebniszugriff über die API-Funktion <code>Adc_ReadGroup</code> zwischen Hardware-Registern, dem ADC-Treiberpuffer und dem anwendungsspezifischen Lesepuffer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier architektonische Domänen bzw. Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>ADC HW</strong>: Beinhaltet die Hardware-Ergebnisregister (<code>HW result register</code>), auf die kein direkter Zugriff über ADC-API-Funktionen unterstützt wird (Hinweistext: <em>„no direct access via ADC API functions supported to ADC HW result register“</em>).</li>\n<li><strong>ADC Driver</strong>: Verantwortlich für das Auslesen der HW-Register und die Zwischenspeicherung in anwendungsseitigen Puffern.</li>\n<li><strong>Application – result buffer (required)</strong>:</li>\n<li><code>G1_ResultBuffer[6]</code>: Puffer für Kanalgruppe 1 mit 6 Elementen, angeordnet als wiederkehrende Sequenzen von <code>G1-CH0</code> und <code>G1-CH1</code> (für 3 Konvertierungsrunden).</li>\n<li><code>G2_ResultBuffer[2]</code>: Puffer für Kanalgruppe 2 mit 2 Elementen (<code>G2-CH2</code> über 2 Konvertierungsrunden).</li>\n<li><code>G3_ResultBuffer[1]</code>: Puffer für Kanalgruppe 3 mit 1 Element (<code>G3-CH3</code> über 1 Konvertierungsrunde).</li>\n<li>Schraffierte Pufferfelder kennzeichnen die Daten der jeweils letzten Konvertierungsrunde (<em>„result of last conversion round“</em>).</li>\n<li><strong>Application – read buffer (required if Adc_ReadGroup is used)</strong>:</li>\n<li><code>G1_ReadBuffer[2]</code>: Lesepuffer für Gruppe 1 mit Feldern für <code>G1-CH0</code> und <code>G1-CH1</code>.</li>\n<li><code>G2_G3_ReadBuffer[1]</code>: Geteilter/wiederverwendeter Lesepuffer für die Einzelkanal-Gruppen 2 oder 3 (<code>G2_CH2 or G3-CH3</code>).</li>\n<li><strong>Schnittstelle</strong>:</li>\n<li>API-Funktion <code>Adc_ReadGroup</code>, welche als Kopiermechanismus zwischen Result Buffer und Read Buffer agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der ADC Driver transferiert Konvertierungsergebnisse aus den <code>HW result register</code> in den jeweiligen anwendungsseitigen <code>result buffer</code> (<code>G1_ResultBuffer</code>, <code>G2_ResultBuffer</code>, <code>G3_ResultBuffer</code>).</li>\n<li>Mehrfach-Konvertierungsrunden werden im <code>result buffer</code> historisiert bzw. akkumuliert (z. B. 3 Runden für G1, 2 Runden für G2, 1 Runde für G3).</li>\n<li>Bei Aufruf von <code>Adc_ReadGroup</code> kopiert der ADC Driver gezielt ausschließlich die Daten der jeweils jüngsten Konvertierungsrunde (<em>„result of last conversion round“</em>, schraffiert dargestellt) aus dem <code>result buffer</code> in den anwendungseigenen <code>read buffer</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für Gruppe 1 werden das schraffierte <code>G1-CH0</code> und <code>G1-CH1</code> in <code>G1_ReadBuffer[2]</code> übertragen.</li>\n<li>Für Gruppe 2 bzw. Gruppe 3 wird das jeweils aktuelle Element (<code>G2-CH2</code> oder <code>G3-CH3</code>) in den gemeinsamen Lesepuffer <code>G2_G3_ReadBuffer[1]</code> kopiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bereitstellung eines Ergebnis-Puffers (<code>result buffer</code>) ist für den Betrieb des ADC Drivers zwingend vorgeschrieben (<code>required</code>).</li>\n<li>Der Lesepuffer (<code>read buffer</code>) ist nur dann erforderlich, wenn Konvertierungsergebnisse über die API <code>Adc_ReadGroup</code> abgerufen werden (<code>required if Adc_ReadGroup is used</code>).</li>\n<li>Direkte Zugriffe der Applikation auf die Hardware-Ergebnisregister über die ADC-Schnittstelle sind normativ untersagt bzw. nicht vorgesehen.</li>\n<li><code>Adc_ReadGroup</code> entkoppelt die Weiterverarbeitung von vorherigen Konvertierungsrunden im Streaming-/Ringpuffer, indem immer nur der Snapshot der jeweils letzten Konvertierungsrunde (ein Messwert pro konfiguriertem Gruppenkanal) in den Zielpuffer übertragen wird.</li>\n<li>Lesepuffer können für disjunkte Gruppenabrufe im Speicher wiederverwendet werden, sofern die Puffergröße mindestens der Kanalanzahl der größten abgefragten Gruppe entspricht.</li>\n</ul>"}, {"id": "FIG-aeeafcfe6a0a4101", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Speicherzugriffsdiagramm des AUTOSAR ADC Drivers (MCAL). Das Diagramm veranschaulicht den Datenfluss und das Puffer-Handling beim Ergebniszugriff über die API-Funktion <code>Adc_ReadGroup</code> zwischen Hardware-Registern, dem ADC-Treiberpuffer und dem anwendungsspezifischen Lesepuffer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier architektonische Domänen bzw. Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>ADC HW</strong>: Beinhaltet die Hardware-Ergebnisregister (<code>HW result register</code>), auf die kein direkter Zugriff über ADC-API-Funktionen unterstützt wird (Hinweistext: <em>„no direct access via ADC API functions supported to ADC HW result register“</em>).</li>\n<li><strong>ADC Driver</strong>: Verantwortlich für das Auslesen der HW-Register und die Zwischenspeicherung in anwendungsseitigen Puffern.</li>\n<li><strong>Application – result buffer (required)</strong>:</li>\n<li><code>G1_ResultBuffer[6]</code>: Puffer für Kanalgruppe 1 mit 6 Elementen, angeordnet als wiederkehrende Sequenzen von <code>G1-CH0</code> und <code>G1-CH1</code> (für 3 Konvertierungsrunden).</li>\n<li><code>G2_ResultBuffer[2]</code>: Puffer für Kanalgruppe 2 mit 2 Elementen (<code>G2-CH2</code> über 2 Konvertierungsrunden).</li>\n<li><code>G3_ResultBuffer[1]</code>: Puffer für Kanalgruppe 3 mit 1 Element (<code>G3-CH3</code> über 1 Konvertierungsrunde).</li>\n<li>Schraffierte Pufferfelder kennzeichnen die Daten der jeweils letzten Konvertierungsrunde (<em>„result of last conversion round“</em>).</li>\n<li><strong>Application – read buffer (required if Adc_ReadGroup is used)</strong>:</li>\n<li><code>G1_ReadBuffer[2]</code>: Lesepuffer für Gruppe 1 mit Feldern für <code>G1-CH0</code> und <code>G1-CH1</code>.</li>\n<li><code>G2_G3_ReadBuffer[1]</code>: Geteilter/wiederverwendeter Lesepuffer für die Einzelkanal-Gruppen 2 oder 3 (<code>G2_CH2 or G3-CH3</code>).</li>\n<li><strong>Schnittstelle</strong>:</li>\n<li>API-Funktion <code>Adc_ReadGroup</code>, welche als Kopiermechanismus zwischen Result Buffer und Read Buffer agiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der ADC Driver transferiert Konvertierungsergebnisse aus den <code>HW result register</code> in den jeweiligen anwendungsseitigen <code>result buffer</code> (<code>G1_ResultBuffer</code>, <code>G2_ResultBuffer</code>, <code>G3_ResultBuffer</code>).</li>\n<li>Mehrfach-Konvertierungsrunden werden im <code>result buffer</code> historisiert bzw. akkumuliert (z. B. 3 Runden für G1, 2 Runden für G2, 1 Runde für G3).</li>\n<li>Bei Aufruf von <code>Adc_ReadGroup</code> kopiert der ADC Driver gezielt ausschließlich die Daten der jeweils jüngsten Konvertierungsrunde (<em>„result of last conversion round“</em>, schraffiert dargestellt) aus dem <code>result buffer</code> in den anwendungseigenen <code>read buffer</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für Gruppe 1 werden das schraffierte <code>G1-CH0</code> und <code>G1-CH1</code> in <code>G1_ReadBuffer[2]</code> übertragen.</li>\n<li>Für Gruppe 2 bzw. Gruppe 3 wird das jeweils aktuelle Element (<code>G2-CH2</code> oder <code>G3-CH3</code>) in den gemeinsamen Lesepuffer <code>G2_G3_ReadBuffer[1]</code> kopiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bereitstellung eines Ergebnis-Puffers (<code>result buffer</code>) ist für den Betrieb des ADC Drivers zwingend vorgeschrieben (<code>required</code>).</li>\n<li>Der Lesepuffer (<code>read buffer</code>) ist nur dann erforderlich, wenn Konvertierungsergebnisse über die API <code>Adc_ReadGroup</code> abgerufen werden (<code>required if Adc_ReadGroup is used</code>).</li>\n<li>Direkte Zugriffe der Applikation auf die Hardware-Ergebnisregister über die ADC-Schnittstelle sind normativ untersagt bzw. nicht vorgesehen.</li>\n<li><code>Adc_ReadGroup</code> entkoppelt die Weiterverarbeitung von vorherigen Konvertierungsrunden im Streaming-/Ringpuffer, indem immer nur der Snapshot der jeweils letzten Konvertierungsrunde (ein Messwert pro konfiguriertem Gruppenkanal) in den Zielpuffer übertragen wird.</li>\n<li>Lesepuffer können für disjunkte Gruppenabrufe im Speicher wiederverwendet werden, sofern die Puffergröße mindestens der Kanalanzahl der größten abgefragten Gruppe entspricht.</li>\n</ul>"}], "trans": [{"from": "FIG-840cebc26558507d", "to": "FIG-4fd4e2d280948a07", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4fd4e2d280948a07", "to": "FIG-be91df9ce822a9ba", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-be91df9ce822a9ba", "to": "FIG-90732dabb33b938b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-90732dabb33b938b", "to": "FIG-aeeafcfe6a0a4101", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
